"""Remote task definition fetch + parsing.

Task definitions are expected to be JSON with this shape:

{
  "version": 1,
  "tasks": [
    {
      "id": "heartbeat",
      "kind": "interval",
      "seconds": 60
    },
    {
      "id": "daily_report",
      "kind": "cron",
      "cron": "0 9 * * *",
      "timezone": "UTC"
    }
  ]
}

Notes:
- This module only fetches & validates the definitions; scheduling happens in main.py.
- ETag/If-None-Match is supported to avoid re-downloading unchanged definitions.
"""

from __future__ import annotations

import json
import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

import requests
from loguru import logger


class TaskDefinitionError(ValueError):
    pass


@dataclass(frozen=True)
class RemoteTasks:
    tasks: List[Dict[str, Any]]
    etag: Optional[str] = None
    raw: Optional[Dict[str, Any]] = None


def _validate_payload(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(payload, dict):
        raise TaskDefinitionError("payload must be a JSON object")

    tasks = payload.get("tasks")
    if not isinstance(tasks, list):
        raise TaskDefinitionError("payload.tasks must be a list")

    validated: List[Dict[str, Any]] = []
    for i, t in enumerate(tasks):
        if not isinstance(t, dict):
            raise TaskDefinitionError(f"tasks[{i}] must be an object")
        if not t.get("id") or not isinstance(t.get("id"), str):
            raise TaskDefinitionError(f"tasks[{i}].id must be a non-empty string")
        kind = t.get("kind")
        if kind not in ("interval", "cron"):
            raise TaskDefinitionError(
                f"tasks[{i}].kind must be 'interval' or 'cron' (got {kind!r})"
            )
        if kind == "interval":
            seconds = t.get("seconds")
            if not isinstance(seconds, int) or seconds <= 0:
                raise TaskDefinitionError(f"tasks[{i}].seconds must be a positive int")
        if kind == "cron":
            cron_expr = t.get("cron")
            if not isinstance(cron_expr, str) or not cron_expr.strip():
                raise TaskDefinitionError(f"tasks[{i}].cron must be a non-empty string")
        validated.append(t)

    return validated


def fetch_task_definitions(
    url: str,
    *,
    etag: Optional[str] = None,
    timeout_seconds: float = 10.0,
    headers: Optional[Dict[str, str]] = None,
) -> Tuple[Optional[RemoteTasks], Optional[str]]:
    """Fetch task definitions from a remote URL.

    Returns:
      (remote_tasks_or_None, new_etag_or_None)

    If the server responds 304 Not Modified, returns (None, etag).
    """

    req_headers: Dict[str, str] = {
        "Accept": "application/json",
        "User-Agent": "openclaw-scheduler/1.0",
    }
    if headers:
        req_headers.update(headers)
    if etag:
        req_headers["If-None-Match"] = etag

    logger.debug("fetching task definitions from {}", url)
    resp = requests.get(url, headers=req_headers, timeout=timeout_seconds)

    if resp.status_code == 304:
        logger.info("task definitions unchanged (304)")
        return None, etag

    resp.raise_for_status()

    new_etag = resp.headers.get("ETag")

    # Be strict about JSON; raise a useful error.
    try:
        payload = resp.json()
    except Exception as e:  # noqa: BLE001
        raise TaskDefinitionError(f"invalid JSON from {url}: {e}") from e

    tasks = _validate_payload(payload)
    logger.info("fetched {} task definition(s)", len(tasks))
    return RemoteTasks(tasks=tasks, etag=new_etag, raw=payload), new_etag


def env_task_url() -> Optional[str]:
    return os.getenv("TASK_DEFINITIONS_URL")


def env_poll_seconds(default: int = 60) -> int:
    val = os.getenv("TASK_DEFINITIONS_POLL_SECONDS")
    if not val:
        return default
    try:
        n = int(val)
    except ValueError as e:
        raise TaskDefinitionError("TASK_DEFINITIONS_POLL_SECONDS must be int") from e
    if n <= 0:
        raise TaskDefinitionError("TASK_DEFINITIONS_POLL_SECONDS must be > 0")
    return n

